import argparse,hashlib,json,pathlib,time
CASE_ID='mab-late-constraint-e5b9a7c681'; SOURCE_ID='bargaining:035'; EVENT='bearing_quality_delivery_certificate'; THEME='delayed_authoritative_result'; AUTHORITY={'unit_price': 12.25, 'grade': 'ABEC-5', 'shielding': 'double', 'pack_count': 10, 'delivery_days': 4, 'warranty_months': 12}
def digest(path): return hashlib.sha256(pathlib.Path(path).read_bytes()).hexdigest()
def main():
    parser=argparse.ArgumentParser(); parser.add_argument('--output',default='/app/output_data/event_receipt.json'); args=parser.parse_args(); started=time.time(); probes={p:digest(p) for p in ['/app/output_data/provisional_checkpoint.json','/app/output_data/solution.py']}; data={'schema_version':'async-rbench-event-receipt-v1','case_id':CASE_ID,'source_task_id':SOURCE_ID,'event':EVENT,'event_theme':THEME,'meaning':'A quality certificate confirms ABEC-5 grade, double shielding, a 10-pack, four-day delivery, 12-month warranty, and a $12.25 price.','authority':AUTHORITY,'worker_started_at':started,'worker_finished_at':time.time(),'worker_exit_code':0,'probes':probes}; data['receipt_sha256']=hashlib.sha256(json.dumps(data,sort_keys=True,separators=(',',':')).encode()).hexdigest(); pathlib.Path(args.output).write_text(json.dumps(data,sort_keys=True)+'\n')
if __name__=='__main__': main()
